        ("I", "Normalization and Schema Design", "1NF, 2NF, 3NF remove duplication; model one-to-many and many-to-many with foreign keys and junction tables.", "CREATE TABLE enrollments (student_id INT, course_id INT, PRIMARY KEY (student_id, course_id));"),
