        ("A", "Indexes and Query Optimisation", "Indexes speed up reads; use `EXPLAIN` to inspect plans; avoid functions on indexed columns and `SELECT *`.", "CREATE INDEX idx_email ON students(email);\nEXPLAIN SELECT * FROM students WHERE email = 'a@x.com';"),
        ("A", "Transactions and ACID", "Group statements so all succeed or none do. InnoDB supports ACID and row-level locking; know isolation levels.", "START TRANSACTION;\nUPDATE acc SET bal = bal - 100 WHERE id = 1;\nUPDATE acc SET bal = bal + 100 WHERE id = 2;\nCOMMIT;"),
        ("A", "Stored Procedures, Functions, Triggers", "Server-side logic: procedures, functions, triggers and events.", "DELIMITER //\nCREATE PROCEDURE get_student(IN sid INT) BEGIN SELECT * FROM students WHERE id = sid; END //"),
