        ("A", "JSON and Full-text Search", "JSON columns with `->>`; full-text indexes for search.", "SELECT data->>'$.city' FROM profiles;"),
        ("A", "Users, Privileges and Security", "Create least-privilege users, avoid SQL injection with prepared statements, enable TLS, rotate passwords.", "CREATE USER 'app'@'%' IDENTIFIED BY '...';\nGRANT SELECT, INSERT ON shop.* TO 'app'@'%';"),
        ("M", "Backup and Restore", "Logical backups with `mysqldump`; binary logs for point-in-time recovery.", "mysqldump -u root -p shop > shop.sql\nmysql -u root -p shop < shop.sql"),
        ("M", "Replication and High Availability", "Source-replica replication, read scaling, failover, Group Replication / InnoDB Cluster.", "SHOW REPLICA STATUS\\G"),
