        ("I", "Window Functions", "`ROW_NUMBER`, `RANK`, `LAG/LEAD`, running totals.", "SELECT id, total, sum(total) OVER (ORDER BY id) FROM orders;"),
        ("I", "JSONB and Arrays", "Store and query semi-structured data with `jsonb` operators and GIN indexes.", "SELECT data->>'city' FROM profiles WHERE data @> '{\"vip\": true}';"),
        ("I", "Views and Materialized Views", "Views store queries; materialized views store results and can be refreshed.", "CREATE MATERIALIZED VIEW monthly AS SELECT date_trunc('month', created_at) m, sum(total) FROM orders GROUP BY 1;"),
        ("A", "Indexes: B-tree, GIN, GiST, BRIN", "Choose index types per workload; partial and covering indexes; verify with `EXPLAIN (ANALYZE, BUFFERS)`.", "CREATE INDEX CONCURRENTLY idx_orders_cust ON orders (customer_id);"),
        ("A", "Transactions, MVCC and Locking", "MVCC lets readers not block writers; isolation levels; row locks (`FOR UPDATE`), advisory locks, deadlocks.", "BEGIN;\nSELECT * FROM acc WHERE id = 1 FOR UPDATE;\nCOMMIT;"),
        ("A", "Functions, Procedures and Triggers (PL/pgSQL)", "Server-side logic with PL/pgSQL, triggers and event triggers.", "CREATE FUNCTION touch() RETURNS trigger AS $$\nBEGIN NEW.updated_at = now(); RETURN NEW; END $$ LANGUAGE plpgsql;"),
        ("A", "Full-text Search", "`tsvector`, `tsquery`, GIN indexes for fast search.", "SELECT * FROM posts WHERE to_tsvector('english', body) @@ to_tsquery('postgres & index');"),
        ("A", "Roles, Permissions and Row-Level Security", "Roles and grants; Row-Level Security policies for multi-tenant data.", "ALTER TABLE docs ENABLE ROW LEVEL SECURITY;"),
        ("A", "Extensions", "`pg_stat_statements`, `postgis`, `pgcrypto`, `pg_trgm`, `pgvector`.", "CREATE EXTENSION pg_trgm;"),
        ("M", "Performance Tuning and VACUUM", "Autovacuum, `ANALYZE`, `work_mem`, `shared_buffers`, connection pooling (PgBouncer), query plans.", "VACUUM (ANALYZE) orders;"),
        ("M", "Backup, Restore and PITR", "`pg_dump`, `pg_restore`, base backups and WAL archiving for point-in-time recovery.", "pg_dump -Fc shop > shop.dump\npg_restore -d shop shop.dump"),
        ("M", "Replication, HA and Partitioning", "Streaming and logical replication, Patroni failover, declarative partitioning.", "CREATE TABLE logs (...) PARTITION BY RANGE (created_at);"),
        ("M", "Real Project: Multi-tenant SaaS Schema", "Schemas/RLS, indexes, migrations, reporting views and backups for a SaaS app.", ""),
